  validation_outcome/resolved_labels: integer (required)
  validation_outcome/bounds: object (required)
  validation_outcome/type_population: object (required)
  validation_outcome/example_only_types: array (required)
  Schema: [validation_outcome](docs/product-truth/schemas/product-truth-validation-outcome.schema.json)

